import Foundation
import Testing
@testable import CliproxyBarCore

/// The panel and this app each compute the quota forecast. Fixtures/forecast-golden.json is
/// one quota history with the forecast the panel computes from it (generated by
/// scripts/forecastGolden.ts in the panel repo, which checks in the same file); this app must
/// arrive at the same numbers. When this fails after a change here, the panel needs the same
/// change, and the other way round.
///
/// CPB_GOLDEN=<file> compares against another file, e.g. one written from the live history.
private struct GoldenFile: Decodable {
    struct Expected: Decodable {
        var weekday: [Double]?
        var weekend: [Double]?
        var recentBurn: Double
        var shortBurn: Double
        var shortPerLong: Double?
        var longRate: [Double]
        var shortRate: [Double]
        var longUsed: [Double]
        var shortUsed: [Double]
        var events: [[Double]]
    }
    var now: Double
    var timeZone: String
    var names: [String]
    var accounts: [String]
    var expected: Expected
    var points: [[Double?]]
}

@Test func forecastMatchesThePanel() throws {
    let path = ProcessInfo.processInfo.environment["CPB_GOLDEN"].map { URL(fileURLWithPath: $0) }
        ?? URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent("Fixtures/forecast-golden.json")
    let file = try JSONDecoder().decode(GoldenFile.self, from: Data(contentsOf: path))
    let expected = file.expected
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = try #require(TimeZone(identifier: file.timeZone))
    let now = Date(timeIntervalSince1970: file.now / 1000)
    let n = now.timeIntervalSince1970
    let points = file.points.map { row in
        HistoryPoint(t: row[0]!, auth: file.accounts[Int(row[1]!)], long_used: row[2], long_reset: row[3],
                     short_used: row[5] == nil ? nil : row[4] ?? 0, short_reset: row[5])
    }

    // The same steps as QuotaModel.pools, so a difference shows where it starts.
    var all: [String: [HistoryPoint]] = [:]
    for p in points { all[p.auth, default: []].append(p) }
    all = all.mapValues { $0.sorted { $0.t < $1.t } }
    let lists = try file.names.map { try #require(all[$0]) }
    let pool = try #require(QuotaModel.pools(points: points, activeAuths: Set(file.names), now: now, calendar: calendar)
        .first { $0.provider == "claude" })
    let seats = try file.names.map { name in try #require(pool.accounts.first { $0.id == name }) }

    var mismatches: [String] = []
    func check(_ what: String, _ got: Double?, _ want: Double?, tolerance: Double = 1e-6) {
        switch (got, want) {
        case (nil, nil): return
        case let (g?, w?) where abs(g - w) <= tolerance * max(1, abs(w)): return
        default: mismatches.append("\(what): this app \(got.map { "\($0)" } ?? "nil"), panel \(want.map { "\($0)" } ?? "nil")")
        }
    }
    func check(_ what: String, _ got: [Double]?, _ want: [Double]?, tolerance: Double = 1e-6) {
        guard let got, let want else {
            if (got == nil) != (want == nil) { mismatches.append("\(what): one side has none") }
            return
        }
        guard got.count == want.count else { mismatches.append("\(what): \(got.count) values, panel \(want.count)"); return }
        for (i, pair) in zip(got, want).enumerated() { check("\(what)[\(i)]", pair.0, pair.1, tolerance: tolerance) }
    }

    let profile = QuotaModel.learnProfile(shape: Array(all.values), pool: lists, now: now, calendar: calendar)
    check("weekday rhythm", profile?.weekday, expected.weekday)
    check("weekend rhythm", profile?.weekend, expected.weekend)
    let recent = lists.reduce(0.0) { $0 + QuotaModel.burn($1, short: false, hours: QuotaModel.recentLongHours, now: n) }
    check("weekly burn, last 5h", recent, expected.recentBurn)
    let shortBurn = seats.reduce(0.0) { $0 + ($1.short?.burnPerHour ?? 0) }
    check("5h burn, last hour", shortBurn, expected.shortBurn)
    let scale = QuotaModel.shortPerLongPoint(lists, now: now)
    check("5h points per weekly point", scale, expected.shortPerLong)

    var longRate: (Date) -> Double = { _ in recent }
    if let profile {
        longRate = QuotaModel.projectedRate(profile, recentBurn: recent, recentHours: QuotaModel.recentLongHours,
                                            now: now, calendar: calendar)
    }
    var shortRate: (Date) -> Double = { _ in shortBurn }
    if let profile, let scale {
        shortRate = QuotaModel.reactiveRate(profile, scale: scale, recentBurn: shortBurn,
                                            recentHours: QuotaModel.shortBurnHours, now: now, calendar: calendar)
    }
    let samples = (0..<85).map { now.addingTimeInterval(Double($0) * 7200) }
    check("projected weekly burn", samples.map(longRate), expected.longRate)
    check("projected 5h burn", samples.map(shortRate), expected.shortRate)

    check("weekly used", seats.map { max($0.long?.used ?? 0, $0.longHighWaterUsed ?? 0) }, expected.longUsed)
    check("5h used", seats.map { max($0.short?.used ?? 0, $0.shortHighWaterUsed ?? 0) }, expected.shortUsed)

    // Times to the second; the panel counts in milliseconds.
    let events = try #require(pool.forecast).events(now: now, calendar: calendar)
    if events.count != expected.events.count {
        mismatches.append("gaps: \(events.count), panel \(expected.events.count)")
    }
    for (i, pair) in zip(events, expected.events).enumerated() {
        check("gap \(i) start", pair.0.start.timeIntervalSince1970, pair.1[0] / 1000, tolerance: 1e-9)
        check("gap \(i) end", pair.0.end.timeIntervalSince1970, pair.1[1] / 1000, tolerance: 1e-9)
        check("gap \(i) working hours", pair.0.working, pair.1[2] / 1000, tolerance: 1e-4)
    }
    if ProcessInfo.processInfo.environment["CPB_GOLDEN"] != nil {
        let day = Date.FormatStyle(timeZone: calendar.timeZone).weekday(.abbreviated).day().hour().minute()
        print("golden: rhythm", profile.map { String(format: "%.1f points a week", $0.perWeek) } ?? "none",
              "| gaps:", events.map { "\($0.start.formatted(day)) – \($0.end.formatted(day))" }.joined(separator: ", "))
        for line in mismatches.prefix(12) { print("golden mismatch:", line) }
    }
    #expect(mismatches.isEmpty, "the panel and the menu bar disagree: \(mismatches.prefix(6).joined(separator: "; "))")
}
